#!/usr/bin/env node
// scaffold-language-toggle.js — v78 ship a canonical i18n language switcher
// component. Reads `app/i18n/index.ts` to detect available locales (or
// uses default ko + en). Emits:
//   - app/components/shared/LanguageToggle.tsx  dropdown menu of locales
//
// Idempotent. Marker: '// Generated by scaffold-language-toggle'.
'use strict';

var fs = require('fs');
var path = require('path');

function parseArgs(argv) {
  var out = {};
  for (var i = 2; i < argv.length; i++) {
    var a = argv[i];
    if (a === '--target') out.target = argv[++i];
    else if (a === '--locales') out.locales = argv[++i]; // comma-separated, e.g. ko,en,ja
    else if (a === '--force') out.force = true;
    else if (a === '--dry-run') out.dryRun = true;
    else if (a === '--verbose' || a === '-v') out.verbose = true;
  }
  if (!out.target) { console.error('Usage: scaffold-language-toggle --target FRONTEND_DIR [--locales ko,en]'); process.exit(1); }
  return out;
}

function marker() { return '// Generated by scaffold-language-toggle — DO NOT EDIT BY HAND. Re-run to refresh.'; }

function writeIfManaged(file, content, force, dryRun) {
  if (fs.existsSync(file)) {
    var existing = fs.readFileSync(file, 'utf-8');
    if (!/Generated by scaffold-language-toggle/.test(existing) && !force) {
      return { written: false, reason: 'exists-handauthored' };
    }
    if (existing === content) return { written: false, reason: 'unchanged' };
  }
  if (dryRun) return { written: false, reason: 'dry-run' };
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, content);
  return { written: true };
}

function detectLocales(target) {
  // Look for locale directories under app/i18n/locales/
  var dir = path.join(target, 'app/i18n/locales');
  if (!fs.existsSync(dir)) return null;
  var locales = fs.readdirSync(dir, { withFileTypes: true })
    .filter(function (d) { return d.isDirectory(); })
    .map(function (d) { return d.name; })
    .filter(function (n) { return /^[a-z]{2}(-[A-Z]{2})?$/.test(n); });
  return locales.length ? locales : null;
}

var LABELS = {
  ko: '한국어', en: 'English', ja: '日本語', zh: '中文', vi: 'Tiếng Việt', th: 'ภาษาไทย',
  es: 'Español', fr: 'Français', de: 'Deutsch', it: 'Italiano', pt: 'Português', ru: 'Русский',
};

function buildComponent(locales) {
  var localesArr = JSON.stringify(locales.map(function (l) {
    return { code: l, label: LABELS[l] || l.toUpperCase() };
  }));
  return [
    marker(),
    "import { useTranslation } from 'react-i18next';",
    "import { Button } from '~/components/ui/button';",
    "import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from '~/components/ui/dropdown-menu';",
    '',
    'const LOCALES = ' + localesArr + ' as const;',
    '',
    'export function LanguageToggle() {',
    '  const { i18n } = useTranslation();',
    "  const current = LOCALES.find((l) => l.code === i18n.language) ?? LOCALES[0];",
    '  return (',
    '    <DropdownMenu>',
    '      <DropdownMenuTrigger asChild>',
    '        <Button variant="ghost" size="sm" data-testid="language-toggle">',
    "          {current.label}",
    '        </Button>',
    '      </DropdownMenuTrigger>',
    '      <DropdownMenuContent align="end" data-testid="language-toggle-menu">',
    '        {LOCALES.map((l) => (',
    '          <DropdownMenuItem',
    '            key={l.code}',
    '            onClick={() => { void i18n.changeLanguage(l.code); }}',
    '            data-testid={`language-toggle-${l.code}`}',
    '          >',
    "            {l.label}",
    '          </DropdownMenuItem>',
    '        ))}',
    '      </DropdownMenuContent>',
    '    </DropdownMenu>',
    '  );',
    '}',
    '',
  ].join('\n');
}

function main() {
  var args = parseArgs(process.argv);
  var locales = args.locales ? args.locales.split(',').map(function (s) { return s.trim(); }).filter(Boolean)
                              : detectLocales(args.target) || ['ko', 'en'];
  var dst = path.join(args.target, 'app/components/shared/LanguageToggle.tsx');
  var r = writeIfManaged(dst, buildComponent(locales), args.force, args.dryRun);
  console.log('scaffold-language-toggle: LanguageToggle.tsx=' + (r.written ? 'wrote' : r.reason) + ' (locales: ' + locales.join(',') + ')');
}

main();
